import{_ as r,c as s,o as n,ag as a,j as i}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"Instalación","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/installation.md","filePath":"es/guide/installation.md","lastUpdated":1794112334000}'),o={name:"es/guide/installation.md"};function t(l,e,c,d,p,m){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h1><h2 id="descargar-nicasa" tabindex="-1">Descargar Nicasa <a class="header-anchor" href="#descargar-nicasa" aria-label="Permalink to &quot;Descargar Nicasa&quot;">​</a></h2><p>Nicasa está disponible exclusivamente para macOS a través del Mac App Store. La app cuesta 4,99 $ y ofrece una compra única con acceso a todas las funciones.</p><h3 id="opciones-de-descarga" tabindex="-1">Opciones de descarga <a class="header-anchor" href="#opciones-de-descarga" aria-label="Permalink to &quot;Opciones de descarga&quot;">​</a></h3><ul><li><strong>Mac App Store</strong>: <a href="https://apps.apple.com/us/app/nicasa-image-viewer/id6756032669?mt=12" target="_blank" rel="noreferrer">Descargar Nicasa</a> —— 4,99 $</li><li><strong>Extensión de Chrome</strong>: <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Extensión de Chrome gratuita</a> —— Gratis</li></ul><h2 id="pasos-de-instalacion" tabindex="-1">Pasos de instalación <a class="header-anchor" href="#pasos-de-instalacion" aria-label="Permalink to &quot;Pasos de instalación&quot;">​</a></h2><h3 id="instalacion-desde-el-mac-app-store" tabindex="-1">Instalación desde el Mac App Store <a class="header-anchor" href="#instalacion-desde-el-mac-app-store" aria-label="Permalink to &quot;Instalación desde el Mac App Store&quot;">​</a></h3><ol><li>Haz clic en el enlace «Descargar Nicasa» de arriba o busca «Nicasa» en el Mac App Store</li><li>Haz clic en «Obtener» o «Comprar» para adquirir la app (4,99 $)</li><li>La app se descargará e instalará automáticamente</li><li>Abre Nicasa desde la carpeta Aplicaciones o el Launchpad</li></ol><h3 id="instalacion-de-la-extension-de-chrome" tabindex="-1">Instalación de la extensión de Chrome <a class="header-anchor" href="#instalacion-de-la-extension-de-chrome" aria-label="Permalink to &quot;Instalación de la extensión de Chrome&quot;">​</a></h3><ol><li>Visita la <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">página de Chrome Web Store</a></li><li>Haz clic en «Añadir a Chrome»</li><li>Confirma la instalación en la ventana emergente</li><li>La extensión se añadirá a tu navegador</li></ol><h4 id="demostracion-de-la-extension-de-chrome" tabindex="-1">Demostración de la extensión de Chrome <a class="header-anchor" href="#demostracion-de-la-extension-de-chrome" aria-label="Permalink to &quot;Demostración de la extensión de Chrome&quot;">​</a></h4>',11),i("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0"}},[i("iframe",{src:"https://www.youtube.com/embed/NJPweIr1J4s",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:"",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%"}})],-1),a('<p><a href="https://www.youtube.com/watch?v=NJPweIr1J4s" target="_blank" rel="noopener">Ver: demostración rápida de la extensión de Chrome de Nicasa</a></p><h2 id="primer-inicio" tabindex="-1">Primer inicio <a class="header-anchor" href="#primer-inicio" aria-label="Permalink to &quot;Primer inicio&quot;">​</a></h2><p>Al abrir Nicasa por primera vez:</p><ol><li>Se te pedirá que concedas los permisos necesarios (grabación de pantalla para las capturas)</li><li>La aplicación buscará imágenes en tu carpeta Imágenes</li><li>Puedes empezar a explorar tu colección de inmediato</li><li>Considera instalar la extensión de Chrome para mejorar la navegación web</li></ol><h3 id="extension-de-sincronizacion-con-el-finder" tabindex="-1">Extensión de sincronización con el Finder <a class="header-anchor" href="#extension-de-sincronizacion-con-el-finder" aria-label="Permalink to &quot;Extensión de sincronización con el Finder&quot;">​</a></h3><p>Nicasa incluye una extensión de la barra de herramientas del Finder para procesar imágenes rápidamente:</p><ol><li>Tras abrir Nicasa, ve a <strong>Ajustes del Sistema</strong> → <strong>Extensiones</strong> → <strong>Extensiones del Finder</strong></li><li>Activa <strong>Nicasa Finder Sync</strong></li><li>Haz clic derecho en la barra de herramientas del Finder → <strong>Personalizar barra de herramientas…</strong></li><li>Arrastra el botón de Nicasa para añadirlo a la barra</li></ol><p>Así podrás optimizar o editar las imágenes seleccionadas directamente desde el Finder.</p><h2 id="requisitos-del-sistema" tabindex="-1">Requisitos del sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to &quot;Requisitos del sistema&quot;">​</a></h2><ul><li><strong>macOS</strong>: 10.13 o posterior</li><li><strong>Almacenamiento</strong>: 54,5 MB de espacio disponible</li><li><strong>Memoria</strong>: 4 GB de RAM mínimo, 8 GB recomendados</li></ul><h2 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to &quot;Permisos&quot;">​</a></h2><p>Nicasa requiere los siguientes permisos:</p><ul><li><strong>Grabación de pantalla</strong>: para la función de captura (se puede conceder más tarde)</li><li><strong>Accesibilidad</strong>: para las funciones del modo superposición (opcional)</li><li><strong>Archivos y carpetas</strong>: acceso a la carpeta Imágenes y a los directorios elegidos por el usuario</li></ul><p>Puedes modificar estos permisos en cualquier momento en Ajustes del Sistema &gt; Privacidad y seguridad.</p><h2 id="solucion-de-problemas-de-instalacion" tabindex="-1">Solución de problemas de instalación <a class="header-anchor" href="#solucion-de-problemas-de-instalacion" aria-label="Permalink to &quot;Solución de problemas de instalación&quot;">​</a></h2><p>Si encuentras problemas durante la instalación:</p><ul><li>Asegúrate de tener privilegios de administrador/root</li><li>Comprueba que tu sistema cumple los requisitos mínimos</li><li>Intenta descargar el archivo de nuevo</li><li>En Linux, asegúrate de tener instaladas las dependencias necesarias</li></ul><p>Para más ayuda, visita nuestra <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">página de incidencias</a>.</p>',18)])])}const g=r(o,[["render",t]]);export{u as __pageData,g as default};
